# Keep best-remind-demo.zip beside app.py; no manual extraction is required.
def _load_best_remind_font():
    zip_path = ROOT / "best-remind-demo.zip"
    if not zip_path.exists():
        return ""
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            font_name = next((n for n in zf.namelist() if n.lower().endswith((".ttf", ".otf"))), None)
            if not font_name:
                return ""
            return base64.b64encode(zf.read(font_name)).decode("ascii")
    except Exception:
        return ""

best_remind_b64 = _load_best_remind_font()
