# ---------- File loader ----------
FILE_ALIASES = {
    "daily": ["clean_daily_activity.csv", "clean_daily_activity(2).csv"],
    "hourly": ["hourly_activity.csv", "hourly_activity(2).csv"],
    "sleep": ["clean_sleep.csv", "clean_sleep(2).csv"],
    "sleep_pairs": ["sleep_activity_pairs.csv", "sleep_activity_pairs(2).csv"],
    "hr": ["hr_hourly.csv", "hr_hourly(2).csv"],
    "hr_join": ["hr_intensity_join.csv", "hr_intensity_join(2).csv"],
    "met": ["met_hourly.csv", "met_hourly(2).csv"],
    "users": ["user_summary.csv", "user_summary(2).csv"],
    "weekly": ["weekly_activity.csv", "weekly_activity(2).csv"],
    "weight": ["clean_weight.csv", "clean_weight(2).csv"],
    "clusters": ["cluster_profiles.csv", "cluster_profiles(2).csv"],
    "sleep_stats": ["sleep_lag_statistics.csv", "sleep_lag_statistics(2).csv"],
    "recommendations": ["recommendations.csv", "recommendations(2).csv"],
    "quality": ["quality_scorecard.csv", "quality_scorecard(2).csv"],
}

def find_file(names):
    # Search processed folder first, then project root.
    for base in (DATA_DIR, ROOT):
        for name in names:
            p = base / name
            if p.exists():
                return p
    return None

@st.cache_data(show_spinner=False)
def load_all():
    out = {}
    for key, names in FILE_ALIASES.items():
        p = find_file(names)
        out[key] = pd.read_csv(p) if p else pd.DataFrame()

    # Parse known date/time columns.
    for key, cols in {
        "daily": ["ActivityDate", "date"],
        "hourly": ["ActivityHour", "activity_date", "date"],
        "sleep": ["SleepDay", "date"],
        "sleep_pairs": ["date"],
        "hr": ["ActivityHour"],
        "hr_join": ["ActivityHour"],
        "met": ["ActivityHour"],
        "users": ["first_date", "last_date"],
        "weight": ["Date", "date"],
    }.items():
        if not out[key].empty:
            for c in cols:
                if c in out[key].columns:
                    out[key][c] = pd.to_datetime(out[key][c], errors="coerce")
    return out

D = load_all()

required = ["daily", "hourly", "sleep"]
missing = [k for k in required if D[k].empty]
if missing:
    st.error(
        "Processed data files not found: "
        + ", ".join(missing)
        + f". Create `{DATA_DIR}` and copy your processed CSV files there."
    )
    st.stop()

daily = D["daily"].copy()
hourly = D["hourly"].copy()
sleep = D["sleep"].copy()
sleep_pairs = D["sleep_pairs"].copy()
hr = D["hr"].copy()
hr_join = D["hr_join"].copy()
users = D["users"].copy()
weekly = D["weekly"].copy()
weight = D["weight"].copy()
clusters = D["clusters"].copy()
sleep_stats = D["sleep_stats"].copy()
recommendations = D["recommendations"].copy()

# Canonical date
if "date" not in daily.columns:
    daily["date"] = pd.to_datetime(daily["ActivityDate"], errors="coerce")
daily["date"] = pd.to_datetime(daily["date"], errors="coerce")
daily = daily.dropna(subset=["date"])

if "valid_day" in daily.columns:
    valid_daily = daily[daily["valid_day"].astype(str).str.lower().isin(["true", "1"])].copy()
    if valid_daily.empty:
        valid_daily = daily.copy()
else:
    valid_daily = daily.copy()

# ---------- Plot helpers ----------
def base_layout(fig, height=390, legend=True):
    fig.update_layout(
        height=height,
        margin=dict(l=20, r=20, t=55, b=30),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color=WHITE, family="Inter"),
        hoverlabel=dict(bgcolor="#111510", font_color=WHITE),
        showlegend=legend,
        legend=dict(orientation="h", y=1.12, x=0),
    )
    fig.update_xaxes(gridcolor=GRID, zeroline=False, linecolor=GRID, tickfont=dict(color=MUTED))
    fig.update_yaxes(gridcolor=GRID, zeroline=False, linecolor=GRID, tickfont=dict(color=MUTED))
    return fig

def line_chart(df, x, y, title, y_title="", fill=False):
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=df[x], y=df[y], mode="lines",
        line=dict(color=LIME, width=2.5),
        fill="tozeroy" if fill else None,
        fillcolor="rgba(198,255,0,.07)",
        hovertemplate="%{x}<br><b>%{y:,.1f}</b><extra></extra>",
    ))
    fig.update_layout(title=dict(text=title, font=dict(size=16)))
    fig.update_yaxes(title=y_title)
    return base_layout(fig, legend=False)

def bar_chart(df, x, y, title, y_title=""):
    fig = go.Figure(go.Bar(
        x=df[x], y=df[y],
        marker=dict(color=LIME, line=dict(color="#E8FF8A", width=.3)),
        hovertemplate="%{x}<br><b>%{y:,.1f}</b><extra></extra>",
    ))
    fig.update_layout(title=dict(text=title, font=dict(size=16)))
    fig.update_yaxes(title=y_title)
    return base_layout(fig, legend=False)

def scatter_chart(df, x, y, title, x_title="", y_title=""):
    fig = go.Figure(go.Scattergl(
        x=df[x], y=df[y], mode="markers",
        marker=dict(color=LIME, size=7, opacity=.5),
        hovertemplate=f"{x}: %{{x:,.1f}}<br>{y}: %{{y:,.1f}}<extra></extra>",
    ))
    # simple regression line if possible
    z = df[[x, y]].replace([np.inf, -np.inf], np.nan).dropna()
    if len(z) >= 3 and z[x].nunique() > 1:
        m, b = np.polyfit(z[x], z[y], 1)
        xx = np.linspace(z[x].min(), z[x].max(), 80)
        fig.add_trace(go.Scatter(
            x=xx, y=m*xx+b, mode="lines",
            line=dict(color=WHITE, width=1, dash="dot"),
            hoverinfo="skip", name="Trend",
        ))
    fig.update_layout(title=dict(text=title, font=dict(size=16)))
    fig.update_xaxes(title=x_title or x)
