    fig.update_layout(title=dict(text=title,font=dict(size=17)),height=500,margin=dict(l=0,r=0,t=55,b=0),paper_bgcolor="rgba(0,0,0,0)",font=dict(color=WHITE),scene=dict(bgcolor="rgba(0,0,0,0)",camera=dict(eye=dict(x=1.55,y=1.55,z=.85)),xaxis=dict(title="Hour",gridcolor="#30352b",backgroundcolor="#070907"),yaxis=dict(title="Weekday",gridcolor="#30352b",backgroundcolor="#070907"),zaxis=dict(title="Avg steps",gridcolor="#30352b",backgroundcolor="#070907")))
    return fig

