def safe_corr(df, a, b):
    z = df[[a,b]].dropna() if a in df.columns and b in df.columns else pd.DataFrame()
    return z[a].corr(z[b]) if len(z) >= 3 else np.nan

def corr_phrase(r):
    if pd.isna(r):
        return "not enough filtered records to estimate the relationship reliably"
    strength = "strong" if abs(r) >= .65 else "moderate" if abs(r) >= .35 else "weak"
    direction = "positive" if r > 0 else "negative" if r < 0 else "near-zero"
    return f"a {strength} {direction} relationship (r = {r:.2f})"


def bmi_orbit_chart(df):
    """Custom BMI orbit: each log becomes a glowing point around the BMI scale."""
    if df.empty or "BMI" not in df.columns:
        return go.Figure()

    x = df.copy()
    x["BMI"] = pd.to_numeric(x["BMI"], errors="coerce")
    x = x.dropna(subset=["BMI"]).sort_values("date" if "date" in x.columns else "BMI")
    if x.empty:
        return go.Figure()

    # Spread records around an orbit while radius reflects BMI.
    angles = np.linspace(0, 2*np.pi, len(x), endpoint=False)
    radii = 1.0 + (x["BMI"].to_numpy() - x["BMI"].mean()) * 0.035
    px = radii * np.cos(angles)
    py = radii * np.sin(angles)

    custom = []
    for _, r in x.iterrows():
        dt = r.get("date", r.get("Date", ""))
        dt_txt = pd.to_datetime(dt).strftime("%d %b %Y") if pd.notna(dt) else "—"
        wt = pd.to_numeric(pd.Series([r.get("WeightKg", np.nan)]), errors="coerce").iloc[0]
        custom.append([dt_txt, wt])

    fig = go.Figure()

    # Reference rings: visual structure, not diagnostic zones.
    for radius, opacity in [(0.72, .13), (1.0, .18), (1.28, .10)]:
        t = np.linspace(0, 2*np.pi, 240)
        fig.add_trace(go.Scatter(
            x=radius*np.cos(t), y=radius*np.sin(t),
            mode="lines", hoverinfo="skip",
            line=dict(color=f"rgba(198,255,0,{opacity})", width=1),
            showlegend=False
        ))

    fig.add_trace(go.Scatter(
        x=px, y=py, mode="lines+markers",
        customdata=np.array(custom, dtype=object),
        marker=dict(
            size=np.clip(11 + (x["BMI"].to_numpy() - x["BMI"].min()) * 1.2, 11, 23),
            color=x["BMI"], colorscale=[[0,"#66704d"],[.45,"#c6ff00"],[1,"#ffffff"]],
            line=dict(color="#c6ff00", width=1),
            showscale=True,
            colorbar=dict(title="BMI", thickness=10, len=.55)
        ),
        line=dict(color="rgba(198,255,0,.45)", width=2),
        hovertemplate="<b>BMI %{marker.color:.1f}</b><br>Date %{customdata[0]}<br>Weight %{customdata[1]:.1f} kg<extra></extra>",
        showlegend=False
    ))

    fig.add_annotation(
        x=0, y=.08, text=f"<b>{x['BMI'].mean():.1f}</b>",
        showarrow=False, font=dict(size=38, color="#f5f7f2")
    )
    fig.add_annotation(
        x=0, y=-.13, text="AVG BMI",
        showarrow=False, font=dict(size=11, color="#c6ff00")
    )

    fig.update_layout(
        height=470, margin=dict(l=15,r=15,t=45,b=15),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#f5f7f2", family="Inter"),
        title=dict(text="BMI orbit", x=.02, font=dict(size=16)),
        xaxis=dict(visible=False, range=[-1.55,1.55]),
        yaxis=dict(visible=False, range=[-1.45,1.45], scaleanchor="x", scaleratio=1),
    )
    return fig

def bmi_band(v):
    if pd.isna(v):
        return "Unavailable"
    if v < 18.5:
        return "Below standard adult range"
    if v < 25:
        return "Standard adult range"
    if v < 30:
        return "Above standard adult range"
    return "Higher adult BMI range"


